function validate([kx, ky, positions]) {
  const inside = v => v >= 0 && v <= 49;
  if (!inside(kx) || !inside(ky)) return 'kx and ky are between 0 and 49.';
  if (positions.length < 1 || positions.length > 15) return 'positions needs 1 to 15 pawns.';
  if (positions.some(p => p.length !== 2 || !inside(p[0]) || !inside(p[1]))) return 'Each pawn is [x, y] with 0 <= x, y <= 49.';
  const squares = new Set(positions.map(([x, y]) => x * 50 + y));
  if (squares.size !== positions.length) return 'Two pawns share a square.';
  if (squares.has(kx * 50 + ky)) return "A pawn cannot start on the knight's square.";
  return null;
}

