function maxMoves(kx, ky, positions) {
  const n = positions.length;
  const points = [...positions, [kx, ky]];
  const dx = [1, 2, 2, 1, -1, -2, -2, -1];
  const dy = [2, 1, -1, -2, -2, -1, 1, 2];
  // dist[i][j]: fewest knight moves from points[i] to points[j], found by a BFS from points[i].
  const dist = [];
  for (const [startX, startY] of points) {
    const steps = Array.from({ length: 50 }, () => new Array(50).fill(-1));
    steps[startX][startY] = 0;
    const queue = [[startX, startY]];
    for (let head = 0; head < queue.length; head++) {
      const [x, y] = queue[head];
      for (let d = 0; d < 8; d++) {
        const nx = x + dx[d];
        const ny = y + dy[d];
        if (nx < 0 || nx >= 50 || ny < 0 || ny >= 50 || steps[nx][ny] !== -1) continue;
        steps[nx][ny] = steps[x][y] + 1;
        queue.push([nx, ny]);
      }
    }
    dist.push(points.map(([x, y]) => steps[x][y]));
  }
  // dp[mask][at]: moves still to come when the pawns in mask remain and the knight is on points[at].
  const full = (1 << n) - 1;
  const dp = Array.from({ length: full + 1 }, () => new Array(n + 1).fill(0));
  for (let mask = 1; mask <= full; mask++) {
    const pawns = [];
    for (let j = 0; j < n; j++) {
      if (mask & (1 << j)) pawns.push(j);
    }
    const aliceTurn = (n - pawns.length) % 2 === 0;
    for (let at = 0; at <= n; at++) {
      if (at < n && (mask & (1 << at))) continue;
      let best = aliceTurn ? -Infinity : Infinity;
      for (const j of pawns) {
        const total = dist[at][j] + dp[mask ^ (1 << j)][j];
        best = aliceTurn ? Math.max(best, total) : Math.min(best, total);
      }
      dp[mask][at] = best;
    }
  }
  return dp[full][n];
}

