function maxMoves(kx, ky, positions) {
  // Knight distance by a level-by-level search with string keys, stopping at the target.
  const distance = (from, to) => {
    const goal = to.join(',');
    let frontier = [from];
    const seen = new Set([from.join(',')]);
    for (let moves = 0; ; moves++) {
      if (frontier.some(p => p.join(',') === goal)) return moves;
      const next = [];
      for (const [x, y] of frontier) {
        for (const [a, b] of [[1, 2], [2, 1]]) {
          for (const [sx, sy] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) {
            const p = [x + sx * a, y + sy * b];
            if (p[0] < 0 || p[0] > 49 || p[1] < 0 || p[1] > 49 || seen.has(p.join(','))) continue;
            seen.add(p.join(','));
            next.push(p);
          }
        }
      }
      frontier = next;
    }
  };
  const squares = [[kx, ky], ...positions];
  const far = squares.map(a => squares.map(b => distance(a, b)));
  // Plain minimax over every order of captures, with no memory of earlier states.
  const play = (left, at, alice) => {
    if (!left.length) return 0;
    const totals = left.map(i => far[at][i] + play(left.filter(j => j !== i), i, !alice));
    return alice ? Math.max(...totals) : Math.min(...totals);
  };
  return play(positions.map((_, i) => i + 1), 0, true);
}

