function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const large = size === 'large';
  // Large inputs use 14 pawns: at the limit of 15, typical O(2^n * n^2) solutions come close to the judge's 2 second limit.
  const count = large ? 14 : 1 + pick(6);
  // Small inputs often crowd into a corner, where knight distances are least regular.
  const span = large ? 50 : [3, 4, 6, 10, 50][pick(5)];
  const baseX = pick(2) ? 0 : 50 - span;
  const baseY = pick(2) ? 0 : 50 - span;
  const used = new Set();
  const squares = [];
  while (squares.length < count + 1) {
    const x = baseX + pick(span);
    const y = baseY + pick(span);
    if (used.has(x * 50 + y)) continue;
    used.add(x * 50 + y);
    squares.push([x, y]);
  }
  const [kx, ky] = squares.pop();
  return [kx, ky, squares];
}
